package com.opensaab.usb;
import android.app.*;import android.os.*;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import org.json.*;
public final class UpgradePreservationInstrumentedTest extends Instrumentation {
 String mode;public void onCreate(Bundle args){mode=args.getString("mode","snapshot");start();}
 String hash(File f)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))>0)md.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:md.digest())s.append(String.format("%02x",b));return s.toString();}
 void files(File dir,File base,JSONObject result)throws Exception{File[] list=dir.listFiles();if(list==null)return;for(File f:list){if(f.isDirectory())files(f,base,result);else result.put(base.toPath().relativize(f.toPath()).toString(),hash(f));}}
 public void onStart(){Bundle r=new Bundle();try{File base=getTargetContext().getDataDir(),snapshot=new File(getTargetContext().getCacheDir(),"open-access-upgrade-before.json");if(mode.equals("snapshot")){JSONObject data=new JSONObject();for(String d:new String[]{"files","no_backup","shared_prefs"})files(new File(base,d),base,data);Files.write(snapshot.toPath(),data.toString().getBytes("UTF-8"));r.putString("stream","PASS: upgrade snapshot retained "+data.length()+" existing firmware/settings/report files\n");}else{JSONObject data=new JSONObject(new String(Files.readAllBytes(snapshot.toPath()),"UTF-8"));Iterator<String> keys=data.keys();int count=0;while(keys.hasNext()){String k=keys.next();File f=new File(base,k);if(!f.isFile()||!hash(f).equals(data.getString(k)))throw new AssertionError("Existing file changed on upgrade: "+k);count++;}r.putString("stream","PASS: all "+count+" existing firmware/settings/report files unchanged across signed-package upgrade\n");}finish(-1,r);}catch(Throwable t){r.putString("stream","FAIL: "+t);finish(0,r);}}
}